                    /** @description Label da fonte de dados externa (INV-ING-001). Ex: external-handball-feed. */
                    sourceLabel: string;
                    /** @description Modo de ingestão (INV-ING-001). Exemplos: batch, webhook, file-drop. Ingestão com normalização automatizada exige payloadSchemaRef + mappingProfile explícitos (INV-ING-003 / DR-ING-002). */
                    ingestionMode: string;
